/*
 * AutoApply CV - LinkedIn walk probe (GENERATED by tools/build-probe.mjs, do not edit).
 *
 * A DRY RUN of the auto-apply flow. It NEVER applies or submits anything.
 * Paste into the DevTools console on a LinkedIn Jobs search page (pause the extension's run first).
 * It opens every job tile, reads the details panel, moves to the next results page and through
 * your search terms, then prints tables and copies a JSON report to the clipboard.
 * Edit CONFIG near the top of the walk section (search terms, pages, open Easy Apply form) before pasting.
 * Stop any time with cpWalkStop(). Tile labels: green = applied, blue = Easy Apply, orange = other, purple = never fully loaded, red = did not open.
 */
// Force a fresh copy of the resolver even if the extension already loaded one on this page.
delete window.CPLinkedInDom;

/*
 * LinkedIn Jobs DOM resolver: update-safe detection with fallback chains.
 *
 * LinkedIn renames CSS classes often, so every question ("where are the job tiles?",
 * "what is this tile's job id?", "is it applied?", "where is the detail pane?") is answered
 * by an ordered list of strategies. The first strategy that gives a plausible answer wins,
 * and the result reports which one it was, so breakages are visible instead of silent.
 *
 * Shared by the content script (loaded before content.js) and tools/linkedin-tile-probe.js.
 * No dependencies; exposes globalThis.CPLinkedInDom.
 */
(function initCPLinkedInDom(global) {
  if (global.CPLinkedInDom) return;

  const JOB_ID_RE = /(\d{9,11})/;
  const JOB_REF_PATTERNS = [
    /jobPosting[:(%3A]+(\d{6,})/i, // urn:li:jobPosting:123 / fsd_jobPosting:123
    /\/jobs\/view\/(\d{6,})/,
    /[?&]currentJobId=(\d{6,})/,
    /[?&]jobId=(\d{6,})/,
    /job[-_]?(?:posting|card|id)[-_:=]+(\d{9,11})/i,
  ];
  const APPLIED_RE =
    /^(you )?(applied|application (submitted|sent|viewed))( (\d+|a|an) (second|minute|hour|day|week|month|year)s? ago| on [a-z ]+| [·•].*)?$/;
  const TILE_WORDS_RE =
    /^(easy apply|promoted|viewed|applied|verified( job)?|actively (reviewing|recruiting)( applicants)?|be an early applicant|\d+ (applicants?|connections?|alumni)|(reposted )?\d+ (minutes?|hours?|days?|weeks?|months?) ago|new)$/;

  const KNOWN_TILE_SELECTORS = [
    ".job-card-container",
    "li.jobs-search-results__list-item",
    ".jobs-search-results-list__list-item",
    "li.scaffold-layout__list-item",
  ];
  const DATA_TILE_SELECTORS = [
    "[data-occludable-job-id]",
    "[data-job-id]",
    "[data-view-name='job-card']",
    "[data-view-name*='job-search-card']",
    "[data-view-name*='job-card']",
  ];
  const KNOWN_DETAIL_SELECTORS = [
    ".jobs-search__job-details",
    ".jobs-details",
    ".job-details-jobs-unified-top-card",
    ".jobs-unified-top-card",
    ".jobs-details-top-card",
    ".scaffold-layout__detail",
  ];
  const DATA_DETAIL_SELECTORS = [
    "[data-view-name*='job-details']",
    "[data-view-name*='job-detail']",
    "[data-view-name*='jobs-details']",
    "[data-view-name*='top-card']",
  ];

  const norm = (t) => String(t || "").toLowerCase().replace(/\s+/g, " ").trim();
  const linesOf = (el) =>
    String(el?.innerText || el?.textContent || "")
      .split(/\n+/)
      .map((l) => l.trim())
      .filter(Boolean);
  // Page chrome, LinkedIn messaging, and our own injected UI (copilot panel, widgets, probe labels),
  // which would otherwise look like a "repeated list" of tiles.
  const EXCLUDED_REGIONS = [
    "header",
    "nav",
    "footer",
    "[role='banner']",
    "[role='navigation']",
    "#msg-overlay",
    ".msg-overlay-container",
    "[id^='cp-']",
    "#li-wa-widget",
    "#li-email-widget",
    "#li-autocommenter-widget",
    "#jso-panel",
    "#jso-post-selector",
    ".cp-probe-label",
  ].join(", ");
  const isChrome = (el) => Boolean(el?.closest?.(EXCLUDED_REGIONS));
  const isVisible = (el) => {
    if (!el?.getBoundingClientRect) return false;
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  };

  function isAppliedLine(text) {
    const t = norm(text);
    return t.length > 0 && t.length <= 60 && APPLIED_RE.test(t);
  }

  function jobIdFromString(value) {
    const raw = String(value || "");
    for (const re of JOB_REF_PATTERNS) {
      const m = raw.match(re);
      if (m?.[1]) return m[1];
    }
    return "";
  }

  /** All distinct job ids referenced by an element and its descendants (attributes only). */
  function jobIdsIn(el, { includeBareNumbers = false } = {}) {
    const ids = new Set();
    const nodes = [el, ...el.querySelectorAll("*")];
    for (const node of nodes) {
      for (const attr of node.attributes || []) {
        if (attr.name === "class" || attr.name === "style") continue;
        const fromRef = jobIdFromString(attr.value);
        if (fromRef) ids.add(fromRef);
        else if (includeBareNumbers && /job|occludable|entity|urn|componentkey/i.test(attr.name)) {
          const m = String(attr.value).match(JOB_ID_RE);
          if (m) ids.add(m[1]);
        }
      }
    }
    return ids;
  }

  function hashText(text) {
    let h = 0;
    for (let i = 0; i < text.length; i += 1) h = (h * 31 + text.charCodeAt(i)) | 0;
    return `txt:${(h >>> 0).toString(36)}`;
  }

  // ---------------------------------------------------------------- job id of a tile
  const JOB_ID_STRATEGIES = [
    [
      "data-attr",
      (tile) => {
        for (const v of [
          tile.getAttribute("data-occludable-job-id"),
          tile.closest("[data-occludable-job-id]")?.getAttribute("data-occludable-job-id"),
          tile.getAttribute("data-job-id"),
          tile.querySelector("[data-job-id], [data-occludable-job-id]")?.getAttribute("data-job-id") ||
            tile.querySelector("[data-occludable-job-id]")?.getAttribute("data-occludable-job-id"),
        ]) {
          if (/^\d+$/.test(String(v || "").trim())) return String(v).trim();
        }
        return "";
      },
    ],
    [
      "job-ref-attr",
      (tile) => {
        const ids = jobIdsIn(tile);
        return ids.size === 1 ? [...ids][0] : "";
      },
    ],
    [
      "link",
      (tile) => jobIdFromString(tile.querySelector("a[href*='/jobs/view/'], a[href*='currentJobId=']")?.href),
    ],
    [
      "numeric-attr",
      (tile) => {
        const ids = jobIdsIn(tile, { includeBareNumbers: true });
        return ids.size === 1 ? [...ids][0] : "";
      },
    ],
    [
      "selected-url",
      (tile) => {
        const selected =
          tile.matches("[aria-current='true'], [aria-selected='true'], [aria-current='page']") ||
          Boolean(tile.querySelector("[aria-current='true'], [aria-selected='true'], [aria-current='page']")) ||
          /active|selected/i.test(String(tile.className || ""));
        return selected ? jobIdFromString(location.href) : "";
      },
    ],
    [
      "text-hash",
      (tile) => {
        const lines = tileLines(tile).filter((l) => !TILE_WORDS_RE.test(norm(l))).slice(0, 3);
        return lines.length ? hashText(norm(lines.join("|"))) : "";
      },
    ],
  ];

  function jobIdOf(tile) {
    if (!tile) return { id: "", via: "none" };
    for (const [via, fn] of JOB_ID_STRATEGIES) {
      try {
        const id = fn(tile);
        if (id) return { id, via };
      } catch {
        // try next strategy
      }
    }
    return { id: "", via: "none" };
  }

  // ---------------------------------------------------------------- tiles
  /** Climb from a seed element to the largest ancestor that still contains exactly one job. */
  function climbToTile(seed, seedId) {
    let best = seed;
    let node = seed;
    while (node?.parentElement && node.parentElement !== document.body) {
      const parent = node.parentElement;
      if (parent.matches("main, header, nav, [role='main']") || parent.querySelector("header, nav")) break;
      if (linesOf(parent).join(" ").length > 1500) break;
      const ids = jobIdsIn(parent);
      if (ids.size > 1 || (seedId && ids.size === 1 && !ids.has(seedId))) break;
      best = parent;
      node = parent;
    }
    return best;
  }

  /** Outermost elements only, excluding the detail pane and page chrome. */
  function cleanTiles(elements, detailPane) {
    const list = Array.from(new Set(elements)).filter(
      (el) => el && !isChrome(el) && (!detailPane || !detailPane.contains(el)),
    );
    return list.filter((el) => !list.some((other) => other !== el && other.contains(el)));
  }

  function tilesFromSeeds(seeds, detailPane) {
    const tiles = [];
    const seen = new Set();
    for (const seed of seeds) {
      if (detailPane?.contains(seed) || isChrome(seed)) continue;
      const id = [...jobIdsIn(seed)][0] || jobIdFromString(seed.href);
      if (!id || seen.has(id)) continue;
      seen.add(id);
      tiles.push(climbToTile(seed, id));
    }
    return seen.size >= 2 ? cleanTiles(tiles, detailPane) : [];
  }

  /** Largest group of same-tag siblings that each look like a job tile. */
  function repeatedSiblingGroups(minCount, detailPane, predicate) {
    const groups = [];
    for (const parent of document.querySelectorAll("ul, ol, div, section")) {
      if (isChrome(parent) || (detailPane && detailPane.contains(parent))) continue;
      const kids = Array.from(parent.children).filter((k) => {
        const text = linesOf(k).join(" ");
        return text.length >= 15 && text.length <= 900 && predicate(k);
      });
      if (kids.length < minCount) continue;
      const tag = kids[0].tagName;
      if (!kids.every((k) => k.tagName === tag)) continue;
      // Real job tiles usually carry words like "Easy Apply", "Promoted", "Viewed", "3 days ago".
      const withTileWords = kids.filter((k) => linesOf(k).some((l) => TILE_WORDS_RE.test(norm(l)))).length;
      groups.push({ parent, kids, score: kids.length + withTileWords * 3 });
    }
    groups.sort((a, b) => b.score - a.score);
    return groups[0]?.kids || [];
  }

  const TILE_STRATEGIES = [
    ["known-classes", (pane) => cleanTiles(document.querySelectorAll(KNOWN_TILE_SELECTORS.join(", ")), pane)],
    ["data-attributes", (pane) => cleanTiles(document.querySelectorAll(DATA_TILE_SELECTORS.join(", ")), pane)],
    [
      "job-ref-attributes",
      (pane) => {
        const seeds = [];
        for (const el of document.querySelectorAll("body *")) {
          for (const attr of el.attributes) {
            if (attr.name !== "class" && attr.name !== "style" && jobIdFromString(attr.value)) {
              seeds.push(el);
              break;
            }
          }
        }
        return tilesFromSeeds(seeds, pane);
      },
    ],
    ["job-links", (pane) => tilesFromSeeds(document.querySelectorAll("a[href*='/jobs/view/'], a[href*='currentJobId=']"), pane)],
    [
      "repeated-list",
      (pane) =>
        repeatedSiblingGroups(5, pane, (k) => {
          const lines = linesOf(k);
          return lines.length >= 2 && lines.length <= 14 && isVisible(k);
        }),
    ],
    [
      "tile-words",
      (pane) =>
        repeatedSiblingGroups(3, pane, (k) => linesOf(k).some((l) => TILE_WORDS_RE.test(norm(l)))),
    ],
  ];

  /**
   * Finds job tiles on a search results page.
   * Returns { tiles, strategy, attempts: [{ strategy, count, error? }] }.
   */
  let lastTileStrategy = "";

  function findJobTiles({ minTiles = 2 } = {}) {
    const pane = findDetailPane().element;
    const attempts = [];
    // Try the strategy that worked last time first: later strategies scan the whole page,
    // and this runs on every DOM change. Falls back to the full chain if it stops matching.
    const ordered = lastTileStrategy
      ? [...TILE_STRATEGIES.filter(([n]) => n === lastTileStrategy), ...TILE_STRATEGIES.filter(([n]) => n !== lastTileStrategy)]
      : TILE_STRATEGIES;
    for (const [strategy, fn] of ordered) {
      try {
        const tiles = fn(pane).filter((t) => t.isConnected);
        attempts.push({ strategy, count: tiles.length });
        if (tiles.length >= minTiles) {
          lastTileStrategy = strategy;
          return { tiles, strategy, attempts };
        }
      } catch (error) {
        attempts.push({ strategy, count: 0, error: String(error?.message || error) });
      }
    }
    return { tiles: [], strategy: "none", attempts };
  }

  // ---------------------------------------------------------------- applied state
  const APPLIED_STRATEGIES = [
    [
      "footer-classes",
      (tile, outside) =>
        Array.from(
          tile.querySelectorAll(
            ".job-card-container__footer-job-state, .job-card-container__footer-item, .job-card-list__footer-wrapper li, .job-card-container__footer-wrapper li, .jobs-card__listdate",
          ),
        ).some((n) => outside(n) && isAppliedLine(n.textContent)),
    ],
    [
      "leaf-text",
      (tile, outside) =>
        Array.from(tile.querySelectorAll("li, span, time, strong, p, div, small")).some(
          (n) => n.childElementCount === 0 && outside(n) && isAppliedLine(n.textContent),
        ),
    ],
    ["text-lines", (tile) => linesOf(tile).some(isAppliedLine)],
    [
      "aria-label",
      (tile, outside) =>
        Array.from(tile.querySelectorAll("[aria-label]")).some(
          (n) => outside(n) && isAppliedLine(n.getAttribute("aria-label")),
        ),
    ],
    [
      "status-attribute",
      (tile) =>
        Array.from(tile.querySelectorAll("[data-test-job-state], [data-job-state], [data-state]")).some((n) =>
          /applied|submitted/i.test(
            `${n.getAttribute("data-test-job-state") || ""} ${n.getAttribute("data-job-state") || ""} ${n.getAttribute("data-state") || ""}`,
          ),
        ),
    ],
  ];

  /** Returns the name of the first strategy that sees an "Applied" marker on the tile, or "". */
  function appliedMethodOf(tile) {
    if (!tile?.querySelectorAll) return "";
    const titleLink = tile.querySelector("a[href*='/jobs/view/'], a[href*='currentJobId=']");
    const outside = (n) => !titleLink || !titleLink.contains(n);
    for (const [name, fn] of APPLIED_STRATEGIES) {
      try {
        if (fn(tile, outside)) return name;
      } catch {
        // try next strategy
      }
    }
    return "";
  }

  /** All strategies' verdicts (for the probe). */
  function appliedReport(tile) {
    const titleLink = tile.querySelector("a[href*='/jobs/view/'], a[href*='currentJobId=']");
    const outside = (n) => !titleLink || !titleLink.contains(n);
    return APPLIED_STRATEGIES.filter(([, fn]) => {
      try {
        return fn(tile, outside);
      } catch {
        return false;
      }
    }).map(([name]) => name);
  }

  function hasEasyApply(tile) {
    return (
      linesOf(tile).some((l) => norm(l).includes("easy apply")) ||
      Boolean(tile.querySelector("[aria-label*='Easy Apply' i]"))
    );
  }

  // ---------------------------------------------------------------- detail pane
  const APPLY_BUTTON_RE = /^(easy apply|apply|applied|apply now|continue applying)\b/;

  function findApplyButton(root = document) {
    for (const el of root.querySelectorAll("button, a[role='button'], a")) {
      if (isChrome(el)) continue;
      const label = norm(`${el.getAttribute("aria-label") || ""}`) || norm(el.textContent);
      if (APPLY_BUTTON_RE.test(label) || /^(easy )?apply to\b/.test(label)) return el;
    }
    return null;
  }

  /**
   * Largest ancestor of `el` that is still about ONE job: stops before it would contain several
   * job ids (that would be the results list too), then returns the biggest candidate that has a
   * heading and a decent amount of text.
   */
  /** Does `root` contain a list: an element with 3+ same-tag children that each hold a few lines of text? */
  function containsList(root) {
    for (const el of [root, ...root.querySelectorAll("ul, ol, div, section")]) {
      const kids = Array.from(el.children).filter((k) => {
        const n = linesOf(k).length;
        return n >= 2 && n <= 14 && linesOf(k).join(" ").length <= 900;
      });
      if (kids.length >= 3 && kids.every((k) => k.tagName === kids[0].tagName)) return true;
    }
    return false;
  }

  function paneAround(el) {
    let node = el;
    let best = null;
    while (node?.parentElement && node.parentElement !== document.body) {
      const parent = node.parentElement;
      if (parent.matches("main, [role='main']") || isChrome(parent)) break;
      // Stop before swallowing the results list: more than one job id, or a sibling branch that is a list.
      if (jobIdsIn(parent, { includeBareNumbers: true }).size > 1) break;
      if (Array.from(parent.children).some((sib) => sib !== node && !isChrome(sib) && containsList(sib))) break;
      node = parent;
      if (node.querySelector("h1, h2, h3") && linesOf(node).join(" ").length > 400) best = node;
    }
    return best;
  }

  const DETAIL_STRATEGIES = [
    ["known-classes", () => document.querySelector(KNOWN_DETAIL_SELECTORS.join(", "))],
    ["data-view-name", () => document.querySelector(DATA_DETAIL_SELECTORS.join(", "))],
    [
      "apply-button",
      () => {
        const btn = findApplyButton();
        return btn ? paneAround(btn) : null;
      },
    ],
    [
      "job-heading",
      () => {
        for (const h of document.querySelectorAll("h1, h2")) {
          if (isChrome(h)) continue;
          const pane = paneAround(h);
          if (pane && /about the job|job description|about the company/i.test(pane.innerText || "")) return pane;
        }
        return null;
      },
    ],
    [
      "scroll-column",
      () => {
        let best = null;
        let bestScore = 0;
        for (const el of document.querySelectorAll("div, section, main > *")) {
          if (isChrome(el) || el.scrollHeight <= el.clientHeight + 50) continue;
          const text = String(el.innerText || "");
          if (!/about the job|job description/i.test(text)) continue;
          const score = text.length;
          if (score > bestScore) {
            best = el;
            bestScore = score;
          }
        }
        return best;
      },
    ],
  ];

  let paneCache = null;

  /** Returns { element, strategy, attempts }. Cached for ~1.5s while the element stays attached. */
  function findDetailPane({ fresh = false } = {}) {
    if (!fresh && paneCache && paneCache.element?.isConnected && Date.now() - paneCache.at < 1500) {
      return paneCache.result;
    }
    const result = findDetailPaneUncached();
    paneCache = { element: result.element, result, at: Date.now() };
    return result;
  }

  function findDetailPaneUncached() {
    const attempts = [];
    for (const [strategy, fn] of DETAIL_STRATEGIES) {
      try {
        const element = fn();
        attempts.push({ strategy, found: Boolean(element) });
        if (element) return { element, strategy, attempts };
      } catch (error) {
        attempts.push({ strategy, found: false, error: String(error?.message || error) });
      }
    }
    return { element: null, strategy: "none", attempts };
  }

  /** Returns how the open job's pane shows it as applied, or "". */
  function detailAppliedMethod(pane = findDetailPane().element) {
    if (!pane) return "";
    if (pane.querySelector(".jobs-apply-button--applied, .post-apply-timeline")) return "applied-class";
    const btn = findApplyButton(pane);
    if (btn && /^applied\b/.test(norm(btn.getAttribute("aria-label") || btn.textContent))) return "applied-button";
    for (const node of pane.querySelectorAll("a, button")) {
      const label = norm(`${node.getAttribute("aria-label") || ""} ${node.textContent || ""}`);
      if (/^(see|view) (your )?application\b/.test(label) || /^application status\b/.test(label)) return "see-application";
    }
    for (const node of pane.querySelectorAll("span, li, p, div, time, small, strong")) {
      if (node.childElementCount === 0 && isAppliedLine(node.textContent)) return "status-text";
    }
    return "";
  }

  // ---------------------------------------------------------------- opening a tile
  /** Dispatches the full pointer/mouse sequence a real click produces (some handlers ignore bare .click()). */
  function realClick(el) {
    const r = el.getBoundingClientRect();
    const opts = { bubbles: true, cancelable: true, view: window, clientX: r.left + r.width / 2, clientY: r.top + Math.min(r.height / 2, 20), button: 0 };
    el.dispatchEvent(new PointerEvent("pointerdown", { ...opts, pointerType: "mouse", isPrimary: true }));
    el.dispatchEvent(new MouseEvent("mousedown", opts));
    el.dispatchEvent(new PointerEvent("pointerup", { ...opts, pointerType: "mouse", isPrimary: true }));
    el.dispatchEvent(new MouseEvent("mouseup", opts));
    el.dispatchEvent(new MouseEvent("click", opts));
  }

  /**
   * Ordered elements to click to open a tile's job: title's clickable element, the title text,
   * a job link, a button inside the tile, the tile itself. Never company/profile links or
   * dismiss/save/hide controls.
   */
  function clickTargetsFor(tile) {
    const targets = [];
    const okEl = (el) => {
      if (!el || !tile.contains(el) || el.closest(INJECTED_LABELS)) return false;
      if (el.tagName === "A" && !/\/jobs\//.test(el.getAttribute("href") || "")) return false;
      const label = norm(`${el.getAttribute?.("aria-label") || ""} ${el.textContent || ""}`);
      return !/^(dismiss|save|unsave|hide|not interested)|dismiss .* job/.test(label);
    };
    const add = (el, via) => {
      if (okEl(el) && !targets.some((t) => t.el === el)) targets.push({ el, via });
    };
    const title = norm(tileTitle(tile));
    const titleEl = Array.from(tile.querySelectorAll("*")).find(
      (e) => e.childElementCount === 0 && !e.closest(INJECTED_LABELS) && title && norm(e.textContent) === title,
    );
    if (titleEl) {
      add(titleEl.closest("a[href*='/jobs/'], [role='button'], button, [tabindex]"), "title-clickable");
      add(titleEl, "title-text");
    }
    add(tile.querySelector("a[href*='/jobs/view/'], a[href*='currentJobId=']"), "job-link");
    add(
      Array.from(tile.querySelectorAll("[role='button'], [tabindex='0']")).find((el) => okEl(el)),
      "tile-button",
    );
    if (tile !== document.body) targets.push({ el: tile, via: "tile" });
    return targets;
  }

  /**
   * Clicks through clickTargetsFor(tile) until the job opens (URL job id or pane heading matches).
   * Resolves { opened, via, tried }.
   */
  async function openTile(tile, { jobId = "", title = "", perTargetMs = 3000 } = {}) {
    const tried = [];
    const opened = () => {
      const urlId = jobIdFromString(location.href);
      if (/^\d+$/.test(jobId) && urlId === jobId) return true;
      const pane = findDetailPane({ fresh: true }).element;
      return Boolean(title && pane && titlesMatch(jobHeading(pane), title));
    };
    if (opened()) return { opened: true, via: "already-open", tried };
    for (const { el, via } of clickTargetsFor(tile)) {
      tried.push(via);
      try {
        el.scrollIntoView({ block: "center" });
        realClick(el);
      } catch {
        continue;
      }
      const start = Date.now();
      while (Date.now() - start < perTargetMs) {
        await new Promise((r) => setTimeout(r, 150));
        if (opened()) return { opened: true, via, tried };
      }
    }
    return { opened: false, via: "", tried };
  }

  // ---------------------------------------------------------------- readiness of the open job
  const INJECTED_LABELS = ".cp-probe-label, .cp-card-outcome-tag, .cp-card-live-badge, .cp-detail-live-indicator";
  const LOADING_SELECTORS =
    "[aria-busy='true'], .artdeco-loader, [class*='skeleton' i], [class*='shimmer' i], [class*='placeholder-loading' i]";
  const CLOSED_RE = /no longer accepting applications|this job is closed|job (has )?expired/i;

  /** Text lines of a tile, ignoring labels injected by the extension or the probes. */
  function tileLines(tile) {
    const injected = new Set();
    for (const el of tile?.querySelectorAll?.(INJECTED_LABELS) || []) {
      for (const line of linesOf(el)) injected.add(line);
    }
    return linesOf(tile).filter((l) => !injected.has(l));
  }

  const GENERIC_HEADING_RE =
    /^(about the (job|company)|job description|are these results helpful|people (also )?viewed|similar jobs|more jobs|meet the hiring team|premium|skills|how you match)/;

  /** The job title heading of a pane (first h1/h2/h3 that is not a generic section heading). */
  function jobHeading(pane) {
    for (const h of pane?.querySelectorAll?.("h1, h2, h3") || []) {
      const t = norm(h.textContent);
      if (t && !GENERIC_HEADING_RE.test(t)) return t;
    }
    return "";
  }

  /** The tile's job title: first text line that is not a badge/status word ("Verified", "Promoted"...). */
  function tileTitle(tile) {
    return tileLines(tile).find((l) => l.length > 2 && !TILE_WORDS_RE.test(norm(l))) || "";
  }

  function titlesMatch(a, b) {
    const x = norm(a).replace(/[^a-z0-9 ]/g, "").slice(0, 30);
    const y = norm(b).replace(/[^a-z0-9 ]/g, "").slice(0, 30);
    if (!x || !y) return false;
    return x.includes(y.slice(0, 20)) || y.includes(x.slice(0, 20));
  }

  /**
   * Is the job details pane fully loaded for this job? Checks each condition separately so a
   * caller can report which one never became true.
   * Pass { jobId, title } of the tile that was clicked.
   */
  function detailReadiness({ jobId = "", title = "" } = {}) {
    const pane = findDetailPane().element;
    if (!pane) return { ready: false, pane: false };
    const urlJobId = jobIdFromString(location.href);
    const heading = jobHeading(pane);
    const idMatch = /^\d+$/.test(jobId) ? urlJobId === jobId : true;
    const titleMatch = title ? titlesMatch(heading, title) : true;
    const btn = findApplyButton(pane);
    const applied = detailAppliedMethod(pane);
    const closed = CLOSED_RE.test(pane.innerText || "");
    const action = applied ? "applied" : btn ? "button" : closed ? "closed" : "";
    const loading = Array.from(pane.querySelectorAll(LOADING_SELECTORS)).some((el) => {
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    });
    const textLength = String(pane.innerText || "").length;
    const description = linesOf(pane).filter((l) => l.length > 40).slice(0, 3).join(" ").slice(0, 300);
    const signature = `${heading}|${action}|${norm(btn?.getAttribute("aria-label") || btn?.textContent || "")}|${description}`;
    return {
      signature,
      ready: Boolean((idMatch || titleMatch) && action && !loading),
      pane: true,
      idMatch,
      titleMatch,
      action,
      loading,
      textLength,
      urlJobId,
      heading: heading.slice(0, 80),
    };
  }

  /**
   * Waits until detailReadiness() is true and the pane text has stopped changing for `stableMs`.
   * Resolves { ready, waitedMs, last } where `last` is the final readiness snapshot.
   */
  async function waitForJobReady(target, { timeoutMs = 12000, stableMs = 700, intervalMs = 200 } = {}) {
    const start = Date.now();
    let last = null;
    let stableSince = 0;
    let lastLength = -1;
    while (Date.now() - start < timeoutMs) {
      last = detailReadiness(target);
      if (last.ready) {
        if (last.signature === lastLength) {
          if (!stableSince) stableSince = Date.now();
          if (Date.now() - stableSince >= stableMs) return { ready: true, waitedMs: Date.now() - start, last };
        } else {
          stableSince = 0;
        }
      } else {
        stableSince = 0;
      }
      lastLength = last.signature ?? -1;
      await new Promise((r) => setTimeout(r, intervalMs));
    }
    return { ready: false, waitedMs: Date.now() - start, last };
  }

  global.CPLinkedInDom = {
    version: 2,
    tileLines,
    tileTitle,
    jobHeading,
    realClick,
    clickTargetsFor,
    openTile,
    detailReadiness,
    waitForJobReady,
    isAppliedLine,
    jobIdFromString,
    jobIdOf,
    findJobTiles,
    appliedMethodOf,
    appliedReport,
    hasEasyApply,
    findDetailPane,
    findApplyButton,
    detailAppliedMethod,
    strategies: {
      tiles: TILE_STRATEGIES.map(([n]) => n),
      jobId: JOB_ID_STRATEGIES.map(([n]) => n),
      applied: APPLIED_STRATEGIES.map(([n]) => n),
      detail: DETAIL_STRATEGIES.map(([n]) => n),
    },
  };
})(typeof window !== "undefined" ? window : globalThis);

// Walk probe body: a dry run of the auto-apply flow. Combined with src/linkedin-dom.js by tools/build-probe.mjs.
// It NEVER applies: it only opens jobs, optionally opens the Easy Apply form and closes it with "Discard".
(async () => {
  // ------------------------------------------------------------------ settings (edit before pasting)
  const CONFIG = {
    searchTerms: [], // e.g. ["Frontend Developer", "React Developer"]; empty = only the current search
    maxPagesPerSearch: 2, // results pages to walk per search term
    maxTilesPerPage: 25, // tiles to open per page
    openEasyApplyForm: false, // true = open the Easy Apply form, record step 1, then close + discard
    delayMs: 1200, // pause between tiles (be gentle with LinkedIn)
    detailTimeoutMs: 15000, // max wait for the job to be fully loaded (id/title + apply button + no spinners)
    stableMs: 700, // the details panel text must stop changing for this long before reading it
  };

  const Dom = window.CPLinkedInDom;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const norm = (t) => String(t || "").toLowerCase().replace(/\s+/g, " ").trim();
  const linesOf = (el) => String(el?.innerText || "").split(/\n+/).map((l) => l.trim()).filter(Boolean);
  const isVisible = (el) => {
    const r = el?.getBoundingClientRect?.();
    return Boolean(r && r.width > 0 && r.height > 0);
  };
  async function waitFor(fn, timeoutMs, intervalMs = 200) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      try {
        const v = fn();
        if (v) return v;
      } catch {
        // keep waiting
      }
      await sleep(intervalMs);
    }
    return null;
  }

  // Never click anything that could submit or advance an application.
  const FORBIDDEN_RE = /\b(submit|send application|review|next|continue|apply now)\b/i;

  let stopped = false;
  window.cpWalkStop = () => {
    stopped = true;
    console.log("[walk] stop requested; finishing current step...");
  };

  const results = [];
  const pages = [];
  const searches = [];
  const status = (msg) => console.log(`%c[walk] ${msg}`, "color:#6366f1");

  // ------------------------------------------------------------------ helpers
  function tileLabel(tile, text, color) {
    tile.querySelector(".cp-probe-label")?.remove();
    const label = document.createElement("div");
    label.className = "cp-probe-label";
    label.textContent = text;
    label.style.cssText = `font:700 11px/1.4 system-ui;color:#fff;background:${color};padding:1px 6px;border-radius:4px;width:fit-content;margin:2px 0;`;
    tile.prepend(label);
    tile.style.outline = `3px solid ${color}`;
    tile.setAttribute("data-cp-probe", "1");
  }

  function detailSnapshot() {
    const pane = Dom.findDetailPane();
    const el = pane.element;
    const heading = el ? Dom.jobHeading(el) : "";
    const btn = el ? Dom.findApplyButton(el) : null;
    return {
      paneVia: pane.strategy,
      urlJobId: Dom.jobIdFromString(location.href),
      title: heading.slice(0, 80),
      applyButton: btn ? norm(btn.getAttribute("aria-label") || btn.textContent).slice(0, 50) : "",
      appliedVia: el ? Dom.detailAppliedMethod(el) : "",
      button: btn,
    };
  }

  // ------------------------------------------------------------------ Easy Apply form (read-only)
  function activeDialog() {
    return Array.from(document.querySelectorAll("[role='dialog'], .artdeco-modal")).find(
      (d) => isVisible(d) && linesOf(d).length > 0,
    );
  }

  async function inspectEasyApplyForm(button) {
    const before = activeDialog();
    button.click();
    const dialog = await waitFor(() => {
      const d = activeDialog();
      return d && d !== before ? d : null;
    }, 6000);
    if (!dialog) return { opened: false };
    await sleep(600);
    const fields = Array.from(dialog.querySelectorAll("input, select, textarea")).filter(
      (f) => f.type !== "hidden" && isVisible(f),
    );
    const labels = Array.from(dialog.querySelectorAll("label, legend"))
      .map((l) => norm(l.textContent).slice(0, 60))
      .filter(Boolean)
      .slice(0, 12);
    const buttons = Array.from(dialog.querySelectorAll("button"))
      .map((b) => norm(b.getAttribute("aria-label") || b.textContent).slice(0, 40))
      .filter(Boolean);
    const info = {
      opened: true,
      step: norm(dialog.querySelector("h2, h3")?.textContent || "").slice(0, 60),
      fieldCount: fields.length,
      labels,
      buttons,
      closed: false,
    };

    // Close: Dismiss/Close (never a forbidden button), then confirm "Discard" if LinkedIn asks.
    const dismiss = Array.from(dialog.querySelectorAll("button")).find((b) => {
      const l = norm(b.getAttribute("aria-label") || b.textContent);
      return /^(dismiss|close)\b/.test(l) && !FORBIDDEN_RE.test(l);
    });
    if (dismiss) dismiss.click();
    else document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    await sleep(700);
    const confirm = activeDialog();
    if (confirm) {
      const discard = Array.from(confirm.querySelectorAll("button")).find((b) =>
        /^discard\b/.test(norm(b.getAttribute("aria-label") || b.textContent)),
      );
      if (discard) {
        discard.click();
        await sleep(600);
      }
    }
    info.closed = !activeDialog();
    return info;
  }

  // ------------------------------------------------------------------ pagination (fallback chain)
  function currentPageNumber() {
    const cur = Array.from(document.querySelectorAll("[aria-current='true'], [aria-current='page']")).find((el) =>
      /^\d+$/.test(norm(el.textContent)),
    );
    return cur ? Number(norm(cur.textContent)) : 1;
  }

  function findNextPageControl() {
    const page = currentPageNumber();
    // Skip the top bar (its "2" notification badges look like page numbers) and our own UI.
    const candidates = Array.from(document.querySelectorAll("button, a")).filter(
      (el) =>
        isVisible(el) &&
        !el.disabled &&
        el.getAttribute("aria-disabled") !== "true" &&
        !el.closest("header, #global-nav, #msg-overlay, [id^='cp-'], .cp-probe-label"),
    );
    const label = (el) => norm(`${el.getAttribute("aria-label") || ""} ${el.textContent || ""}`);
    const chain = [
      ["aria-next", () => candidates.find((el) => /^(view )?next( page)?\b/.test(norm(el.getAttribute("aria-label"))))],
      ["page-number", () => candidates.find((el) => norm(el.getAttribute("aria-label")) === `page ${page + 1}` || norm(el.textContent) === String(page + 1))],
      ["next-text", () => candidates.find((el) => /^next\b/.test(norm(el.textContent)))],
      ["more-results", () => candidates.find((el) => /^(see|show|load) more (jobs|results)\b/.test(label(el)))],
    ];
    for (const [via, fn] of chain) {
      const el = fn();
      if (el) return { el, via };
    }
    return null;
  }

  function firstTileKey() {
    const { tiles } = Dom.findJobTiles();
    return tiles.length ? Dom.jobIdOf(tiles[0]).id : "";
  }

  async function goToNextPage() {
    const control = findNextPageControl();
    if (!control) return { moved: false, via: "none" };
    const beforeKey = firstTileKey();
    const beforePage = currentPageNumber();
    control.el.scrollIntoView({ block: "center" });
    control.el.click();
    const changed = await waitFor(() => firstTileKey() && firstTileKey() !== beforeKey, 10000, 300);
    return { moved: Boolean(changed), via: control.via, from: beforePage, to: currentPageNumber() };
  }

  // ------------------------------------------------------------------ search box (fallback chain)
  function findSearchInput() {
    const inputs = Array.from(document.querySelectorAll("input")).filter((i) => isVisible(i) && i.type !== "hidden");
    const hint = (i) => norm(`${i.getAttribute("aria-label") || ""} ${i.getAttribute("placeholder") || ""}`);
    const chain = [
      ["title-label", () => inputs.find((i) => /title|skill|company/.test(hint(i)) && !/location|city/.test(hint(i)))],
      ["describe-job", () => inputs.find((i) => /describe|job you want|search jobs/.test(hint(i)))],
      ["jobs-combobox", () => inputs.find((i) => i.getAttribute("role") === "combobox" && /job/.test(hint(i)))],
      ["any-search", () => inputs.find((i) => /search/.test(hint(i)) && !/location|city|messag/.test(hint(i)))],
    ];
    for (const [via, fn] of chain) {
      const el = fn();
      if (el) return { el, via };
    }
    return null;
  }

  async function runSearch(term) {
    const found = findSearchInput();
    if (!found) return { ok: false, via: "none" };
    const input = found.el;
    const beforeKey = firstTileKey();
    input.focus();
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
    setter.call(input, term);
    input.dispatchEvent(new Event("input", { bubbles: true }));
    await sleep(400);
    for (const type of ["keydown", "keypress", "keyup"]) {
      input.dispatchEvent(new KeyboardEvent(type, { key: "Enter", code: "Enter", keyCode: 13, which: 13, bubbles: true }));
    }
    input.form?.requestSubmit?.();
    const changed = await waitFor(() => firstTileKey() && firstTileKey() !== beforeKey, 12000, 300);
    return { ok: Boolean(changed), via: found.via };
  }

  // ------------------------------------------------------------------ walk one results page
  async function walkPage(searchLabel, pageNo) {
    const found = Dom.findJobTiles();
    const page = { search: searchLabel, page: pageNo, tilesVia: found.strategy, tiles: found.tiles.length, opened: 0, failedToOpen: 0 };
    status(`"${searchLabel}" page ${pageNo}: ${found.tiles.length} tiles via ${found.strategy}`);

    const seen = new Set();
    for (const tile of found.tiles.slice(0, CONFIG.maxTilesPerPage)) {
      if (stopped) break;
      if (!tile.isConnected) continue;
      const { id: tileId, via: idVia } = Dom.jobIdOf(tile);
      if (seen.has(tileId)) continue;
      seen.add(tileId);

      // Read the tile ignoring labels added by the probes or the extension.
      const tileTitle = norm(Dom.tileTitle(tile)).slice(0, 50);
      const tileEasyApply = Dom.hasEasyApply(tile);
      const tileApplied = Dom.appliedMethodOf(tile);

      tile.scrollIntoView({ block: "center" });
      tileLabel(tile, "opening…", "#6366f1");
      // Click through the target chain (title → title text → job link → tile button → tile)
      // until LinkedIn actually selects this job.
      const open = await Dom.openTile(tile, { jobId: tileId, title: tileTitle });

      // Wait for FULL readiness: this job's id/title in the pane, an apply action rendered,
      // no loading placeholders, and the pane text stable for CONFIG.stableMs.
      const readiness = await Dom.waitForJobReady(
        { jobId: tileId, title: tileTitle },
        { timeoutMs: CONFIG.detailTimeoutMs, stableMs: CONFIG.stableMs },
      );
      const after = open.opened && (readiness.ready || readiness.last?.idMatch || readiness.last?.titleMatch) ? detailSnapshot() : null;

      const row = {
        search: searchLabel,
        page: pageNo,
        tileJobId: tileId,
        idVia,
        tileTitle,
        tileEasyApply,
        tileApplied: tileApplied || "no",
        opened: Boolean(after),
        clickVia: open.via || `failed (tried ${open.tried.join(" > ")})`,
        ready: readiness.ready,
        openMs: after ? readiness.waitedMs : null,
        notReadyBecause: readiness.ready
          ? ""
          : [
              !readiness.last?.pane && "no details pane",
              readiness.last?.pane && !readiness.last.idMatch && !readiness.last.titleMatch && "pane still shows another job",
              readiness.last?.pane && !readiness.last.action && "no apply button/applied/closed state",
              readiness.last?.loading && "still loading",
            ]
              .filter(Boolean)
              .join(", ") || "text kept changing",
        urlJobId: after?.urlJobId || "",
        idMatchesUrl: Boolean(after && after.urlJobId && after.urlJobId === tileId),
        detailTitle: after?.title || "",
        detailVia: after?.paneVia || "",
        applyButton: after?.applyButton || "(none)",
        detailApplied: after?.appliedVia || "no",
        form: "",
      };

      if (after && CONFIG.openEasyApplyForm && after.button && /easy apply/.test(after.applyButton) && !after.appliedVia) {
        const form = await inspectEasyApplyForm(after.button);
        row.form = form.opened
          ? `step "${form.step}", ${form.fieldCount} fields, buttons: ${form.buttons.join("/")}${form.closed ? "" : " (NOT CLOSED)"}`
          : "did not open";
        row.formDetail = form;
      }

      results.push(row);
      if (row.opened) page.opened += 1;
      else page.failedToOpen += 1;

      const applied = row.tileApplied !== "no" || row.detailApplied !== "no";
      const color = !row.opened ? "#ef4444" : !row.ready ? "#a855f7" : applied ? "#10b981" : row.applyButton.includes("easy apply") ? "#0ea5e9" : "#f59e0b";
      const text = !row.opened
        ? "did not open"
        : !row.ready
          ? `not ready: ${row.notReadyBecause}`
          : applied
          ? `APPLIED (${row.tileApplied !== "no" ? row.tileApplied : row.detailApplied})`
          : `${row.applyButton || "no apply button"} · ${row.openMs}ms`;
      tileLabel(tile, `#${results.length} ${text}`, color);
      console.log(`[walk] #${results.length} ${row.tileTitle} → ${text}${row.idMatchesUrl ? "" : " (url id differs)"}`);
      await sleep(CONFIG.delayMs);
    }
    pages.push(page);
  }

  // ------------------------------------------------------------------ main
  if (!Dom) {
    console.error("[walk] CPLinkedInDom missing");
    return;
  }
  document.querySelectorAll(".cp-probe-label").forEach((el) => el.remove());
  console.log("%cAutoApply CV walk probe (dry run, never applies)", "font-weight:700;font-size:14px;color:#6366f1");
  console.log("[walk] Pause the extension's run first. Stop any time with cpWalkStop().", CONFIG);

  const terms = CONFIG.searchTerms.length ? CONFIG.searchTerms : [null];
  for (const [index, term] of terms.entries()) {
    if (stopped) break;
    let label = term || `current (${new URL(location.href).searchParams.get("keywords") || "search"})`;
    if (term) {
      status(`searching "${term}"…`);
      const s = await runSearch(term);
      searches.push({ term, ...s });
      if (!s.ok) {
        if (index > 0 || s.via === "none") {
          status(`search "${term}" did not change the results (input via ${s.via}); skipping`);
          continue;
        }
        // First term: the page may already be showing this search, so walk what is there.
        status(`results unchanged after searching "${term}"; walking the current results`);
        s.note = "results unchanged (probably already showing this search)";
      }
      label = term;
      await sleep(1500);
    }
    for (let pageNo = 1; pageNo <= CONFIG.maxPagesPerSearch && !stopped; pageNo += 1) {
      await walkPage(label, pageNo);
      if (pageNo === CONFIG.maxPagesPerSearch || stopped) break;
      const move = await goToNextPage();
      pages[pages.length - 1].nextPage = move;
      if (!move.moved) {
        status(`no further page (next control via ${move.via})`);
        break;
      }
      status(`moved to page ${move.to} via ${move.via}`);
      await sleep(1500);
    }
  }

  // ------------------------------------------------------------------ report
  const summary = {
    tilesOpened: results.filter((r) => r.opened).length,
    tilesFailedToOpen: results.filter((r) => !r.opened).length,
    tilesNotFullyReady: results.filter((r) => r.opened && !r.ready).length,
    alreadyApplied: results.filter((r) => r.tileApplied !== "no" || r.detailApplied !== "no").length,
    appliedOnTileButNotDetail: results.filter((r) => r.tileApplied !== "no" && r.detailApplied === "no").length,
    appliedInDetailButNotTile: results.filter((r) => r.tileApplied === "no" && r.detailApplied !== "no").length,
    easyApplyButtons: results.filter((r) => /easy apply/.test(r.applyButton)).length,
    externalApplyButtons: results.filter((r) => r.opened && /^apply\b/.test(r.applyButton) && !/easy/.test(r.applyButton)).length,
    noApplyButton: results.filter((r) => r.opened && r.applyButton === "(none)").length,
    tileIdNotMatchingUrl: results.filter((r) => r.opened && /^\d+$/.test(r.tileJobId) && !r.idMatchesUrl).length,
    avgOpenMs: Math.round(
      results.filter((r) => r.openMs).reduce((s, r) => s + r.openMs, 0) / Math.max(1, results.filter((r) => r.openMs).length),
    ),
    formsOpened: results.filter((r) => r.formDetail?.opened).length,
    formsNotClosed: results.filter((r) => r.formDetail?.opened && !r.formDetail.closed).length,
  };
  const report = { url: location.href, at: new Date().toISOString(), config: CONFIG, summary, searches, pages, results };
  window.__cpWalk = report;

  console.log("%c[walk] done", "font-weight:700;color:#10b981");
  console.table(summary);
  console.table(pages);
  console.table(results.map(({ formDetail, ...r }) => r));
  try {
    if (typeof copy === "function") {
      copy(JSON.stringify(report, null, 2));
      console.log("[walk] Full report copied to clipboard (also in window.__cpWalk). cpProbeClear() removes labels.");
    }
  } catch {
    console.log("[walk] Full report is in window.__cpWalk");
  }
  window.cpProbeClear =
    window.cpProbeClear ||
    (() => {
      document.querySelectorAll("[data-cp-probe]").forEach((el) => {
        el.style.outline = "";
        el.removeAttribute("data-cp-probe");
      });
      document.querySelectorAll(".cp-probe-label").forEach((el) => el.remove());
    });
})();
